  protected cache: ICacheStore;

  constructor(dbInstance?: DrizzleDb, cacheStore?: ICacheStore) {
    super(dbInstance);
    this.cache = cacheStore ?? CacheFactory.create();
  }

  protected getCacheKey(...parts: string[]): string {
    return parts.join(":");
  }
}

